// Allocates a CelList hash entry, links it into the bucket for nHashKey and returns it. The tail is MOV [EAX],ECX at 006047ed with EAX still holding the new node, and CELCMP_AllocateCelListKeyThreadSafe (006048c0) tail-returns it - nothing writes EAX after the call. CELCMP_AllocateCelListKey then writes six fields through the result (+0x18/+0x1c/+0x24/+0x28/+0x2c), so typing this void made every cel-list key allocation write through an uninitialised pointer.
template<> ::CELLIST * TSHashTable<CELLIST, HASHKEY_NONE>::New(uint32_t dwHashVal, HASHKEY_NONE * pKey, uint32_t nExtraBytes, uint32_t dwFlags) {
    TSLink<::CELLIST>* ppBucketSlot;
    uint32_t nBucketIndex = dwHashVal & this->nSlotMask;
    int32_t bRehashed = this->MonitorFullness(nBucketIndex);
    if (bRehashed) {
      nBucketIndex = dwHashVal & this->nSlotMask;
    }

    ::CELLIST* pNewEntry = this->pVtable->InternalNew(this, this->tSlotListArray.m_data + nBucketIndex, nExtraBytes, dwFlags);
    if (pNewEntry) {
      ppBucketSlot = (TSLink<::CELLIST>*)((uintptr_t)&pNewEntry->m_hashval + this->tFullList.m_linkoffset);
    } else {
      ppBucketSlot = &this->tFullList.m_terminator;
    }

    TSLink<::CELLIST>* pTVar1 = ppBucketSlot->m_prevlink;
    if (pTVar1) {
      int* pBackLink;
      nBucketIndex = ppBucketSlot->m_next;
      if ((int)nBucketIndex < 0) {
        pBackLink = (int*)~nBucketIndex;
      } else {
        pBackLink = (int*)((int)ppBucketSlot + (nBucketIndex - pTVar1->m_next));
      }

      *pBackLink = (int)pTVar1;
      ppBucketSlot->m_prevlink->m_next = ppBucketSlot->m_next;
      ppBucketSlot->m_prevlink = 0;
      ppBucketSlot->m_next = 0;
    }

    pTVar1 = this->tFullList.m_terminator.m_prevlink;
    ppBucketSlot->m_prevlink = pTVar1;
    ppBucketSlot->m_next = pTVar1->m_next;
    pTVar1->m_next = (int)pNewEntry;
    this->tFullList.m_terminator.m_prevlink = ppBucketSlot;
    pNewEntry->m_hashval = dwHashVal;
    return pNewEntry;
}

